import json
with open('/workspace/contracts/openapi.contract.json') as f:
    contract = json.load(f)
# Detailed introspection of all endpoints including request bodies
def get_schema_name(s):
    if not isinstance(s, dict):
        return '?'
    if '$ref' in s:
        return s['$ref'].split('/')[-1]
    return 'inline'

def dump_schema(schema, schemas, depth=0):
    if depth > 3:
        return 'deep'
    name = get_schema_name(schema)
    if name == 'inline':
        return json.dumps(schema)[:200]
    if name in schemas:
        return json.dumps(schemas[name])[:300]
    return name

for path in sorted(contract['paths']):
    for method, op in contract['paths'][path].items():
        if method in ['get','post','put','delete','patch']:
            opid = op.get('operationId', '')
            print(f'\n=== {method.upper()} {path} ({opid}) ===')
            # Parameters
            for param in op.get('parameters', []):
                schema = param.get('schema', {})
                print(f'  Param [{param.get("name")}] in {param.get("in")} : {get_schema_name(schema)}')
            # Request body
            rb = op.get('requestBody', {})
            content = rb.get('content', {})
            json_content = content.get('application/json', {})
            schema = json_content.get('schema', {})
            if schema:
                print(f'  RequestBody: {get_schema_name(schema)}')
                print(f'    Required: {rb.get("required", False)}')
            # Responses
            for status_code, resp in op.get('responses', {}).items():
                cont = resp.get('content', {})
                jc = cont.get('application/json', {})
                s = jc.get('schema', {})
                print(f'  Response {status_code}: {get_schema_name(s)}')
EOF"}

