import (
	"os"
	"strconv"
	"time"
)

type Config struct {
	ListenAddr   string
	PostgresURL  string
	MongoURI     string
	RedisAddr    string
	AdminUser    string
	AdminPass    string
	JWTSecret    string
	OfferTTL     time.Duration
	LocationStale time.Duration
	WorkerStale   time.Duration
}

func Load() Config {
	return Config{
		ListenAddr:    env("LISTEN_ADDR", "127.0.0.1:8080"),
		PostgresURL:   env("DATABASE_URL", "postgres://arena:arena@127.0.0.1:5432/arena?sslmode=disable"),
		MongoURI:      env("MONGODB_URI", "mongodb://127.0.0.1:27017"),
		RedisAddr:     env("REDIS_URL_HOST", "127.0.0.1:6379"),
		AdminUser:     env("ADMIN_USERNAME", "admin"),
		AdminPass:     env("ADMIN_PASSWORD", "admin"),
		JWTSecret:     env("JWT_SECRET", "lablogistics-dev-secret"),
		OfferTTL:      envDur("OFFER_TTL", 5*time.Minute),
		LocationStale: envDur("LOCATION_STALE", 30*time.Minute),
		WorkerStale:   envDur("WORKER_STALE", 30*time.Minute),
	}
}

func env(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

func envDur(k string, def time.Duration) time.Duration {
	if v := os.Getenv(k); v != "" {
		if d, err := time.ParseDuration(v); err == nil {
			return d
		}
		if n, err := strconv.Atoi(v); err == nil {
			return time.Duration(n) * time.Second
		}
	}
	return def
}"}

{"security_risk":"LOW","summary":"Create postgres store","command":"create","path":"/workspace/backend/internal/store/postgres.go","file_text":"package store

import (
	"context"
	"embed"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

//go:embed migrations/*.sql
var migrations embed.FS

type Postgres struct {
	pool *pgxpool.Pool
}

func NewPostgres(ctx context.Context, url string) (*Postgres, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, err
	}
	cfg.MaxConns = 16
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, err
	}
	p := &Postgres{pool: pool}
	if err := p.Ping(ctx); err != nil {
		return nil, err
	}
	return p, nil
}

func (p *Postgres) Pool() *pgxpool.Pool { return p.pool }

func (p *Postgres) Ping(ctx context.Context) error {
	c, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	return p.pool.Ping(c)
}

func (p *Postgres) Close() { p.pool.Close() }

// Reset drops and recreates all schema and indexes in a single transaction.
func (p *Postgres) Reset(ctx context.Context) error {
	conn, err := p.pool.Acquire(ctx)
	if err != nil {
		return err
	}
	defer conn.Release()
	drop := `
		DROP TABLE IF EXISTS audit CASCADE;
		DROP TABLE IF EXISTS timeline CASCADE;
		DROP TABLE IF EXISTS handoff CASCADE;
		DROP TABLE IF EXISTS assignment CASCADE;
		DROP TABLE IF EXISTS journey_stop CASCADE;
		DROP TABLE IF EXISTS journey CASCADE;
		DROP TABLE IF EXISTS sample CASCADE;
		DROP TABLE IF EXISTS request CASCADE;
		DROP TABLE IF EXISTS sample_type CASCADE;
		DROP TABLE IF EXISTS connection CASCADE;
		DROP TABLE IF EXISTS location CASCADE;
		DROP TABLE IF EXISTS user_session CASCADE;
		DROP TABLE IF EXISTS app_user CASCADE;
		DROP TABLE IF EXISTS serviceability_snapshot CASCADE;
		DROP TABLE IF EXISTS app_meta CASCADE;
	`
	if _, err := conn.Exec(ctx, drop); err != nil {
		return fmt.Errorf("drop: %w", err)
	}
	entries, err := migrations.ReadDir("migrations")
	if err != nil {
		return err
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".sql") {
			names = append(names, e.Name())
		}
	}
	sort.Strings(names)
	for _, n := range names {
		b, err := migrations.ReadFile("migrations/" + n)
		if err != nil {
			return err
		}
		if _, err := conn.Exec(ctx, string(b)); err != nil {
			return fmt.Errorf("migration %s: %w", n, err)
		}
	}
	return nil
}

// EnsureSchema is idempotent for re-runs after Reset; mainly no-op since reset creates fresh.
func (p *Postgres) EnsureSchema(ctx context.Context) error {
	entries, err := migrations.ReadDir("migrations")
	if err != nil {
		return err
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".sql") {
			names = append(names, e.Name())
		}
	}
	sort.Strings(names)
	for _, n := range names {
		b, err := migrations.ReadFile("migrations/" + n)
		if err != nil {
			return err
		}
		if _, err := p.pool.Exec(ctx, string(b)); err != nil {
			// idempotent — ignore "already exists"
			if !strings.Contains(err.Error(), "already exists") {
				return fmt.Errorf("migration %s: %w", n, err)
			}
		}
	}
	return nil
}

// Used by handlers; convenience wrappers below.

func (p *Postgres) QueryRow(ctx context.Context, sql string, args ...any) pgx.Row {
	return p.pool.QueryRow(ctx, sql, args...)
}

func (p *Postgres) Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error) {
	return p.pool.Query(ctx, sql, args...)
}

func (p *Postgres) Exec(ctx context.Context, sql string, args ...any) (int64, error) {
	t, err := p.pool.Exec(ctx, sql, args...)
	if err != nil {
		return 0, err
	}
	return t.RowsAffected(), nil
}

func (p *Postgres) Begin(ctx context.Context) (pgx.Tx, error) {
	return p.pool.Begin(ctx)
}"}

