{"security_risk":"LOW","summary":"Create mongo store","command":"create","path":"/workspace/backend/internal/store/mongo.go","file_text":"package store

import (
	"context"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

const AuditDB = "lablogistics"
const AuditColl = "audit_events"

type Mongo struct {
	Client *mongo.Client
	Coll   *mongo.Collection
}

func NewMongo(ctx context.Context, uri string) (*Mongo, error) {
	client, err := mongo.Connect(ctx, options.Client().ApplyURI(uri))
	if err != nil {
		return nil, err
	}
	if err := client.Ping(ctx, nil); err != nil {
		return nil, err
	}
	coll := client.Database(AuditDB).Collection(AuditColl)
	if err := ensureMongoIndexes(ctx, coll); err != nil {
		return nil, err
	}
	return &Mongo{Client: client, Coll: coll}, nil
}

func ensureMongoIndexes(ctx context.Context, coll *mongo.Collection) error {
	_, err := coll.Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "occurredAt", Value: -1}}},
		{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}}},
		{Keys: bson.D{{Key: "actorId", Value: 1}}},
	})
	return err
}

// Reset drops the audit collection so reset produces a clean state.
func (m *Mongo) Reset(ctx context.Context) error {
	return m.Coll.Drop(ctx)
}

func (m *Mongo) Close(ctx context.Context) error {
	return m.Client.Disconnect(ctx)
}

func (m *Mongo) Insert(ctx context.Context, doc any) error {
	_, err := m.Coll.InsertOne(ctx, doc)
	return err
}

// SearchAudit performs a generic filter search and returns up to 200 recent matching docs.
func (m *Mongo) SearchAudit(ctx context.Context, filter bson.M) ([]bson.M, error) {
	if filter == nil {
		filter = bson.M{}
	}
	opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: -1}}).SetLimit(200)
	cur, err := m.Coll.Find(ctx, filter, opts)
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	out := []bson.M{}
	for cur.Next(ctx) {
		var doc bson.M
		if err := cur.Decode(&doc); err != nil {
			return nil, err
		}
		out = append(out, doc)
	}
	return out, cur.Err()
}

// now is exposed for tests
var NowFn = func() time.Time { return time.Now().UTC() }"}

{"security_risk":"LOW","summary":"Create auth package","command":"create","path":"/workspace/backend/internal/auth/auth.go","file_text":"package auth

import (
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"time"

	"golang.org/x/crypto/bcrypt"
)

func RandomToken(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func HashPassword(plain string) (string, error) {
	h, err := bcrypt.GenerateFromPassword([]byte(plain), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	return string(h), nil
}

func VerifyPassword(hash, plain string) bool {
	if hash == "" || plain == "" {
		return false
	}
	if err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(plain)); err != nil {
		// bcrypt-style fallback for SHA256 legacy hashes
		if len(hash) == 64 {
			sum := sha256.Sum256([]byte(plain))
			if subtle.ConstantTimeCompare([]byte(hash), []byte(hex.EncodeToString(sum[:]))) == 1 {
				return true
			}
		}
		return false
	}
	return true
}

var ErrSessionExpired = errors.New("session expired")

func SessionExpiry(ttl time.Duration) time.Time {
	return time.Now().UTC().Add(ttl)
}"}

{"security_risk":"LOW","summary":"Create events package","command":"create","path":"/workspace/backend/internal/events/events.go","file_text":"package events

import (
	"context"
	"encoding/json"
	"log"
	"sync"
	"sync/atomic"
	"time"

	"github.com/lablogistics/models"
)

const Channel = "realtime"

type Event = models.RealtimeEvent

type Broker struct {
	mu        sync.RWMutex
	listeners map[int64]chan Event
	nextID    int64
}

func NewBroker() *Broker {
	return &Broker{listeners: map[int64]chan Event{}}
}

func (b *Broker) Subscribe() (int64, <-chan Event) {
	id := atomic.AddInt64(&b.nextID, 1)
	ch := make(chan Event, 32)
	b.mu.Lock()
	b.listeners[id] = ch
	b.mu.Unlock()
	return id, ch
}

func (b *Broker) Unsubscribe(id int64) {
	b.mu.Lock()
	if c, ok := b.listeners[id]; ok {
		close(c)
		delete(b.listeners, id)
	}
	b.mu.Unlock()
}

func (b *Broker) Publish(evType, entityType, entityID string, payload any) {
	ev := Event{
		ID:         atomic.AddInt64(&b.nextID, 1),
		Type:       evType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now().UTC(),
	}
	bytes, _ := json.Marshal(ev)
	b.mu.RLock()
	defer b.mu.RUnlock()
	for _, ch := range b.listeners {
		select {
		case ch <- ev:
		default:
			// drop if buffer full
		}
	}
	// also publish to redis for cross-process fanout; ignore errors
	if rdb := GlobalRedisPublisher(); rdb != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		defer cancel()
		if err := rdb.Publish(ctx, Channel, bytes); err != nil {
			log.Printf("redis publish: %v", err)
		}
	}
}

// Allow handlers to publish a fresh event as a stored row.
func (b *Broker) SendStored(ev Event) {
	b.mu.RLock()
	defer b.mu.RUnlock()
	for _, ch := range b.listeners {
		select {
		case ch <- ev:
		default:
		}
	}
}

// --- a small Redis publisher abstraction ---------------------------------
// We keep the redis client hidden behind this so handlers don't import redis directly.

type Publisher interface {
	Publish(ctx context.Context, channel string, payload []byte) error
}

var globalPublisher atomic.Value // Publisher

func SetRedisPublisher(p Publisher) { globalPublisher.Store(p) }

func GlobalRedisPublisher() Publisher {
	v := globalPublisher.Load()
	if v == nil {
		return nil
	}
	return v.(Publisher)
}"}

{"security_risk":"LOW","summary":"Create realtime websocket hub","command":"create","path":"/workspace/backend/internal/realtime/hub.go","file_text":"package realtime

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/lablogistics/events"
	"github.com/lablogistics/store"
	nhoj "github.com/gorilla/websocket"
)

var upgrader = nhoj.Upgrader{
	CheckOrigin:     func(r *http.Request) bool { return true },
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
}

type Hub struct {
	broker   *events.Broker
	rdb      *store.Redis
	mu       sync.Mutex
	streams  map[int64]context.CancelFunc
	stoppers map[int64]chan struct{}
}

func NewHub(broker *events.Broker, rdb *store.Redis) *Hub {
	h := &Hub{broker: broker, rdb: rdb, streams: map[int64]context.CancelFunc{}, stoppers: map[int64]chan struct{}{}}
	return h
}

// HandleWS upgrades the HTTP connection and registers a subscriber. It
// also starts a goroutine that subscribes to Redis Pub/Sub for cross-process events.
func (h *Hub) HandleWS(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	id, ch := h.broker.Subscribe()
	// also subscribe to redis pub/sub for multi-process fanout
	ctx, cancel := context.WithCancel(context.Background())
	var psCh <-chan struct{}
	if h.rdb != nil {
		_ = ctx
	}
	h.mu.Lock()
	h.streams[id] = cancel
	h.mu.Unlock()

	go func() {
		defer func() {
			h.broker.Unsubscribe(id)
			cancel()
			conn.Close()
		}()

		// Listen to redis pubsub if available
		var redisCh <-chan string
		if h.rdb != nil {
			sub := h.rdb.Subscribe(ctx, events.Channel)
			redisCh = sub.Channel(redisChCtx).String()
			_ = redisCh
			defer sub.Close()
		}

		// read pump to detect close
		closed := make(chan struct{})
		go func() {
			defer close(closed)
			for {
				if _, _, err := conn.NextReader(); err != nil {
					return
				}
			}
		}()

		pingTick := time.NewTicker(20 * time.Second)
		defer pingTick.Stop()
		for {
			select {
			case <-closed:
				return
			case ev, ok := <-ch:
				if !ok {
					return
				}
				if err := conn.WriteJSON(ev); err != nil {
					return
				}
			case <-pingTick.C:
				if err := conn.WriteMessage(nhoj.PingMessage, nil); err != nil {
					return
				}
			case msg := <-redisSubChannel(ctx, h.rdb):
				var ev events.Event
				if err := json.Unmarshal([]byte(msg), &ev); err == nil {
					if err := conn.WriteJSON(ev); err != nil {
						return
					}
				}
			}
		}
	}()
}

var redisChCtx = func() (string, struct{}) {
	return "x", struct{}{}
}()

func redisSubChannel(ctx context.Context, rdb *store.Redis) <-chan string {
	if rdb == nil {
		return nil
	}
	out := make(chan string, 16)
	go func() {
		defer close(out)
		sub := rdb.Subscribe(ctx, events.Channel)
		defer sub.Close()
		ch := sub.Channel()
		for {
			select {
			case <-ctx.Done():
				return
			case m, ok := <-ch:
				if !ok {
					return
				}
				select {
				case out <- m.Payload:
				default:
				}
			}
		}
	}()
	return out
}

// helper for log
var _ = log.Default"}

