type loginResp struct {
	Data struct {
		SessionToken string       `json:"sessionToken"`
		UserID       string       `json:"userId"`
		Roles        []string     `json:"roles"`
		ActiveRole   string       `json:"activeRole"`
	} `json:"data"`
}

func (s *Server) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req loginReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.Username == "" || req.Password == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "username and password are required")
		return
	}
	var u models.User
	var rolesRaw string
	var assignedNode, assignedLab string
	var certsRaw string
	row := s.PG.QueryRow(r.Context(), `SELECT id, username, password_hash, full_name, array_to_string(roles, ','), active_role, assigned_node, assigned_lab, array_to_string(certifications, ','), available, created_at FROM app_user WHERE username=$1`, req.Username)
	if err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.FullName, &rolesRaw, &u.ActiveRole, &assignedNode, &assignedLab, &certsRaw, &u.Available, &u.CreatedAt); err != nil {
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "username or password is incorrect")
		return
	}
	if !auth.VerifyPassword(u.PasswordHash, req.Password) {
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "username or password is incorrect")
		return
	}
	if rolesRaw != "" {
		for _, p := range splitComma(rolesRaw) {
			u.Roles = append(u.Roles, models.Role(p))
		}
	}
	if u.ActiveRole == "" && len(u.Roles) > 0 {
		u.ActiveRole = u.Roles[0]
		_, _ = s.PG.Exec(r.Context(), "UPDATE app_user SET active_role=$1 WHERE id=$2", u.ActiveRole, u.ID)
	}
	if certsRaw != "" {
		u.Certs = splitComma(certsRaw)
	}
	u.AssignedNode = assignedNode
	u.AssignedLab = assignedLab

	tok, err := newSession(r.Context(), s.PG, u.ID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	resp := loginResp{}
	resp.Data.SessionToken = tok
	resp.Data.UserID = u.ID
	rolesOut := make([]string, 0, len(u.Roles))
	for _, rl := range u.Roles {
		rolesOut = append(rolesOut, string(rl))
	}
	resp.Data.Roles = rolesOut
	resp.Data.ActiveRole = string(u.ActiveRole)
	s.Audit.Record(r.Context(), u.ID, string(u.ActiveRole), "authenticate", "user", u.ID, true, map[string]any{"ip": r.RemoteAddr})
	writeJSON(w, http.StatusOK, resp)
}

