func (s *Server) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	var req createUserReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.Username == "" || req.Password == "" || req.FullName == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "username, password, fullName required")
		return
	}
	if len(req.Roles) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_json", "at least one role required")
		return
	}
	hash, err := auth.HashPassword(req.Password)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	id := "usr_" + randID()
	active := req.Roles[0]
	rolesPG := pgTextArr(req.Roles)
	certsPG := pgTextArr(req.Certifications)
	_, err = s.PG.Exec(r.Context(), `INSERT INTO app_user (id, username, password_hash, full_name, roles, active_role, assigned_node, assigned_lab, certifications) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, req.Username, hash, req.FullName, rolesPG, active, req.AssignedNodeID, req.AssignedLabID, certsPG)
	if err != nil {
		if isUniqueViolation(err) {
			writeError(w, http.StatusConflict, "user_exists", "username already exists")
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	uid := r.Context().Value(ctxUserID).(string)
	role := r.Context().Value(ctxUserRole).(string)
	s.Audit.Record(r.Context(), uid, string(role), "create_user", "user", id, true, map[string]any{"username": req.Username, "roles": req.Roles})

	out := userEnvelope{}
	out.Data.UserID = id
	out.Data.Username = req.Username
	out.Data.FullName = req.FullName
	out.Data.Roles = req.Roles
	out.Data.ActiveRole = active
	out.Data.AssignedNodeID = req.AssignedNodeID
	out.Data.AssignedLabID = req.AssignedLabID
	out.Data.Certifications = req.Certifications
	out.Data.Available = true
	writeJSON(w, http.StatusCreated, out)
}

