		writeError(w, http.StatusNotFound, "user_not_found", "user not found")
		return
	}
	out := readUserResp{}
	out.Data.UserID = u.ID
	out.Data.Username = u.Username
	out.Data.FullName = u.FullName
	out.Data.Roles = splitComma(rolesRaw)
	out.Data.ActiveRole = u.ActiveRole
	out.Data.AssignedNodeID = assignedNode
	out.Data.AssignedLabID = assignedLab
	out.Data.Certifications = splitComma(certsRaw)
	out.Data.Available = u.Available
	writeJSON(w, http.StatusOK, out)
}

func splitComma(s string) []string {
	out := []string{}
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

