{"security_risk":"LOW","summary":"Helper string utilities","command":"create","path":"/workspace/backend/internal/httpapi/strings_helper.go","file_text":"package httpapi

import (
	"fmt"
	"strconv"
	"strings"
)

func splitColon(s string) []string {
	if i := strings.IndexByte(s, ':'); i >= 0 {
		return []string{s[:i], s[i+1:]}
	}
	return []string{s}
}

// itoa handles small integers as Postgres placeholder indices.
func itoa(n int) string {
	return strconv.Itoa(n)
}

// joinComma joins parts with a comma.
func joinComma(parts []string) string {
	out := ""
	for i, p := range parts {
		if i > 0 {
			out += ","
		}
		out += p
	}
	return out
}

// asStrArr safely coerces pgx array-decoded value (could be []string).
func asStrArr(v any) []string {
	switch t := v.(type) {
	case []string:
		return t
	case string:
		return splitComma(t)
	case []byte:
		return splitComma(string(t))
	case nil:
		return nil
	}
	return nil
}

// dummy usage so we don't trigger unused warnings in tiny builds
var _ = fmt.Sprintf"}

