func (s *Server) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	var req checkServiceabilityReq
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", err.Error())
		return
	}
	if req.SampleTypeID == "" || req.TargetLaboratoryID == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "sampleTypeId and targetLaboratoryId required")
		return
	}
	res, err := s.Serv.Check(r.Context(), req.Origin, req.SampleTypeID, req.TargetLaboratoryID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
