func (s *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	uid := r.Context().Value(ctxUserID).(string)
	role := string(r.Context().Value(ctxUserRole).(models.Role))
	var req listRoleWorkReq
	_ = readJSON(r, &req)
	if req.ActiveRole == "" {
		req.ActiveRole = role
	}
	items := []map[string]any{}

	switch models.Role(req.ActiveRole) {
	case models.RoleRequester:
		rows, err := s.PG.Query(r.Context(), `SELECT id, request_id, sample_type_id, sealed, status, current_holder_id, delivery_deadline FROM sample WHERE requester_id=$1 ORDER BY requested_at DESC`, uid)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, rid, st string
				var sealed, status, holder string
				var dl time.Time
				if err := rows.Scan(&id, &rid, &st, &sealed, &status, &holder, &dl); err == nil {
					items = append(items, map[string]any{"sampleId": id, "requestId": rid, "sampleTypeId": st, "sealed": sealed, "status": status, "currentHolderId": holder, "deliveryDeadline": dl})
				}
			}
		}
	case models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam:
		// Show assignments where the worker is or could be the actor (their node/lab assignments also included)
		var assignedNode, assignedLab string
		_ = s.PG.QueryRow(r.Context(), `SELECT assigned_node, assigned_lab FROM app_user WHERE id=$1`, uid).Scan(&assignedNode, &assignedLab)
		// active assignments held
		rows, err := s.PG.Query(r.Context(), `SELECT id, journey_id, sample_id, kind, from_location_id, to_location_id, status, offer_expires_at FROM assignment WHERE (worker_id=$1 OR (worker_id='' AND status='offered' AND ($2<>'' OR $3<>''))) ORDER BY offered_at DESC LIMIT 50`, uid, assignedNode, assignedLab)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var a models.Assignment
				if err := rows.Scan(&a.ID, &a.JourneyID, &a.SampleID, &a.Kind, &a.FromLocationID, &a.ToLocationID, &a.Status, &a.OfferExpiresAt); err == nil {
					items = append(items, map[string]any{"assignmentId": a.ID, "journeyId": a.JourneyID, "sampleId": a.SampleID, "kind": a.Kind, "fromLocationId": a.FromLocationID, "toLocationId": a.ToLocationID, "status": a.Status, "offerExpiresAt": a.OfferExpiresAt})
				}
			}
		}
		// samples currently held
		rows2, err := s.PG.Query(r.Context(), `SELECT id, sample_type_id, sealed, status, target_lab_id, delivery_deadline FROM sample WHERE current_holder_id=$1`, uid)
		if err == nil {
			defer rows2.Close()
			for rows2.Next() {
				var id, st string
				var sealed, status, lab string
				var dl time.Time
				if err := rows2.Scan(&id, &st, &sealed, &status, &lab, &dl); err == nil {
					items = append(items, map[string]any{"sampleId": id, "sampleTypeId": st, "sealed": sealed, "status": status, "targetLaboratoryId": lab, "deliveryDeadline": dl})
				}
			}
		}
	case models.RoleDispatcher, models.RoleAdministrator:
		rows, err := s.PG.Query(r.Context(), `SELECT id, sample_type_id, sealed, status, delivery_deadline FROM sample WHERE status NOT IN ('received','cancelled') ORDER BY requested_at DESC LIMIT 100`)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, st string
				var sealed, status string
				var dl time.Time
				if err := rows.Scan(&id, &st, &sealed, &status, &dl); err == nil {
					items = append(items, map[string]any{"sampleId": id, "sampleTypeId": st, "sealed": sealed, "status": status, "deliveryDeadline": dl})
				}
			}
		}
	}
	out := listRoleWorkEnvelope{}
	out.Data.Role = req.ActiveRole
	out.Data.Items = items
	writeJSON(w, http.StatusOK, out)
}

