			var available bool
			if err := rows3.Scan(&id, &name, &rolesRaw, &activeRole, &available, &node, &lab); err == nil {
				workers = append(workers, map[string]any{
					"userId": id, "fullName": name, "roles": splitComma(rolesRaw), "activeRole": activeRole,
					"available": available, "assignedNodeId": node, "assignedLaboratoryId": lab,
				})
			}
		}
	}

	sampleSummaries := []map[string]any{}
	rows4, err := s.PG.Query(r.Context(), `SELECT id, sample_type_id, sealed, status, current_holder_id, current_lat, current_lon, location_at, target_lab_id, delivery_deadline FROM sample`)
	if err == nil {
		defer rows4.Close()
		staleThreshold := time.Now().Add(-s.Cfg.WorkerStale)
		for rows4.Next() {
			var id, st, sealed, status, holder string
			var lat, lon float64
			var locAt time.Time
			var lab string
			var dl time.Time
			if err := rows4.Scan(&id, &st, &sealed, &status, &holder, &lat, &lon, &locAt, &lab, &dl); err == nil {
				sampleSummaries = append(sampleSummaries, map[string]any{
					"sampleId": id, "sampleTypeId": st, "sealed": sealed, "status": status,
					"currentHolderId": holder,
					"currentLocation": map[string]any{"latitude": lat, "longitude": lon},
					"locationStale": locAt.Before(staleThreshold),
					"locationRecordedAt": locAt,
					"targetLaboratoryId": lab, "deliveryDeadline": dl,
				})
			}
		}
	}

	snap, _ := s.Serv.LastPublished(r.Context())
	out := operationsStateEnvelope{}
	out.Data.Locations = locations
	out.Data.Connections = connections
	out.Data.Workers = workers
	out.Data.SampleSummaries = sampleSummaries
	out.Data.SnapshotVersion = snap.Version
	writeJSON(w, http.StatusOK, out)
}"}

