				l.Capacity.AvailableUnits = l.Capacity.CapacityUnits - l.Capacity.ReservedUnits
				l.Capacity.CooledAvailableUnits = l.Capacity.CooledCapacityUnits - l.Capacity.CooledReservedUnits
				locations = append(locations, l)
			}
		}
