{"security_risk":"LOW","summary":"Add Ready and ApplyMigrations","command":"str_replace","path":"/workspace/backend/internal/store/postgres.go","old_str":"func (p *Postgres) Close() { p.pool.Close() }","new_str":"func (p *Postgres) Close() { p.pool.Close() }

func (p *Postgres) Ready(ctx context.Context) bool {
	c, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	return p.pool.Ping(c) == nil
}

// ApplyMigrations runs the SQL files idempotently, treating "already exists" errors as success.
func (p *Postgres) ApplyMigrations(ctx context.Context, dir string) error {
	if dir == "" {
		return p.EnsureSchema(ctx)
	}
	// Optionally read from disk; otherwise use embedded
	entries, err := migrations.ReadDir("migrations")
	if err != nil {
		return err
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".sql") {
			names = append(names, e.Name())
		}
	}
	sort.Strings(names)
	for _, n := range names {
		b, err := migrations.ReadFile("migrations/" + n)
		if err != nil {
			return err
		}
		if _, err := p.pool.Exec(ctx, string(b)); err != nil {
			if !strings.Contains(err.Error(), "already exists") {
				return fmt.Errorf("migration %s: %w", n, err)
			}
		}
	}
	return nil
}"}

{"security_risk":"LOW","summary":"Create hub.go","command":"create","path":"/workspace/backend/internal/realtime/hub.go","file_text":"package realtime

import (
	"context"
	"net/http"
	"sync"
	"time"

	"lablogistics/internal/events"

	nhoj "github.com/gorilla/websocket"
)

var upgrader = nhoj.Upgrader{
	CheckOrigin:     func(r *http.Request) bool { return true },
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
}

// PubSub is the minimal interface needed for cross-process event fan-out.
type PubSub interface {
	Subscribe(ctx context.Context, channel string) (Subscription, error)
	Publish(ctx context.Context, channel, payload string) error
}

type Subscription interface {
	Channel() <-chan string
	Close() error
}

type Hub struct {
	broker *events.Broker
	ps     PubSub
	mu     sync.Mutex
	cancels map[int64]context.CancelFunc
}

func NewHub(broker *events.Broker, ps PubSub) *Hub {
	return &Hub{broker: broker, ps: ps, cancels: map[int64]context.CancelFunc{}}
}

func (h *Hub) HandleWS(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	id, ch := h.broker.Subscribe()
	ctx, cancel := context.WithCancel(context.Background())
	h.mu.Lock()
	h.cancels[id] = cancel
	h.mu.Unlock()

	go func() {
		defer func() {
			h.broker.Unsubscribe(id)
			cancel()
			_ = conn.Close()
		}()

		var external <-chan string
		if h.ps != nil {
			sub, err := h.ps.Subscribe(ctx, events.Channel)
			if err == nil {
				external = sub.Channel()
				defer sub.Close()
			}
		}

		closed := make(chan struct{})
		go func() {
			defer close(closed)
			for {
				if _, _, err := conn.NextReader(); err != nil {
					return
				}
			}
		}()

		ping := time.NewTicker(20 * time.Second)
		defer ping.Stop()

		for {
			select {
			case <-closed:
				return
			case ev, ok := <-ch:
				if !ok {
					return
				}
				_ = conn.WriteJSON(ev)
			case <-ping.C:
				_ = conn.WriteMessage(nhoj.PingMessage, nil)
			case msg, ok := <-external:
				if !ok {
					external = nil
					continue
				}
				_ = conn.WriteMessage(nhoj.TextMessage, []byte(msg))
			}
		}
	}()
}"}

